// One-page résumé PDFs, generated by `yarn build-resume` from the site's own content.
// They live in public/ so their URLs stay plain and stable, without a build hash.
const RESUMES = {
  en: "/jeffrey-rengifo-cv-en.pdf",
  es: "/jeffrey-rengifo-cv-es.pdf",
};

/** The résumé in the given language, falling back to English. */
export const resumeUrl = (language) => RESUMES[language] ?? RESUMES.en;
